(async () => {
        const props = await Entity.properties('garden pump');
        const isRelation = props.find(p => p.name === 'state')?.dataType === 'relation';
        let value = 'on';
        const display = value;
        if (isRelation) {
            const target = (await Entity.filter({})).find(t => t.name.toLowerCase() === String(value).toLowerCase());
            if (!target) throw new Error('Entity not found: ' + value);
            value = target.id;
        }
        await Entity.set('garden pump', 'state', value);
        return { entity: 'garden pump', property: 'state', value: display };
    })()

if ((await Entity.get('Weather', 'rain')) == 0 && (await Entity.get('Garden', 'moisture')) <= 30) {
await Entity.set('Garden pump', 'state', 'on');
}

if ((new Date(await Entity.get('Weather', 'sunset')) <= new Date())) {
await Entity.set('Garden lamp', 'color', [0,255,255]);
}

if ((await Entity.get('Bathroom motion sensor', 'motion')) == 'on') {
const prev0 = await Entity.get('Bathroom lamp', 'state');
await Entity.set('Bathroom lamp', 'state', 'on');
await Time.sleep(120000);
await Entity.set('Bathroom lamp', 'state', prev0);
}

if ((await Entity.heldFor('Office motion sensor', 'motion', '==', 'off', 900))) {
await Entity.set('Office lamp', 'state', 'off');
}

if ((await Entity.heldFor('Office motion sensor', 'motion', '==', 'off', 900))) {
await Entity.set('Office lamp', 'state', 'off');
}

const now = new Date();
const sunrise = new Date(await Entity.get('Weather', 'sunrise'));
const sunset = new Date(await Entity.get('Weather', 'sunset'));
const isDark = now < sunrise || now > sunset;
const lamps = await Entity.filter({type: 'lamp'});
for (const lamp of lamps) {
  if (lamp.name === 'Garden lamp' && isDark) {
    // Skip turning off garden lamp when it's dark
    continue;
  }
  await Entity.set(lamp.name, 'state', 'off');
}

